1	// Tập 7 · VẬT THỂ MỚI (C3, D-010 quy tắc 4) — chưa vào lib3d.js (không sửa toolkit trong phiên này). Gen kênh: low-poly, màu kênh (E2).
2	//  N1 MonthTrack — "đường tháng": một ô = MỘT khoản trả tháng; ô giống hệt nhau; trái → phải = thời gian.
3	//   Bố cục lịch: cột = một năm (cols = 12 ô), cột nối nhau trái → phải; trong cột, tháng 1 ở mép trước (+z), tháng 12 ở mép sau.
4	//   180 ô = 15 cột đủ. Ô quá n (trễ) = warn, sáng theo PHẦN như W10 (14,6 → 14 ô đủ + ô thứ 15 sáng 60 %). Vạch 15 năm (sau ô n) = ink-muted, đứng yên.
5	//   Trả thêm: lớp mỏng `cushion` trên mỗi ô (extra) hoặc một khối `cushion` trên ô thứ 12 mỗi cột (yearly) — khối = đúng thể tích 12 lớp.
6	//  PayBar — thanh khoản trả tháng (ink), phần trên mức warnAbove = warn (giá của khoản dự phòng). Chiều cao = USD × scale.
7	//  Bill — một tờ đô la low-poly (màu vật liệu tiền của lib3d, không chữ) cho S25.
8	import * as THREE from 'three';
9	
10	export const TRACK = { ink: '#F2F4F7', warn: '#F2B441', extra: '#269783', mark: '#9AA4B2', empty: '#2A303B' };   // ink · warn · cushion · ink-muted · grid (E2)
11	const mat = (c, o = {}) => new THREE.MeshStandardMaterial({ color: c, roughness: 0.8, transparent: true, ...o });
12	const cl01 = (x) => Math.min(1, Math.max(0, x));
13	
14	// ---------------------------------------------------------------- N1 đường tháng (gốc toạ độ = góc trước-trái của ô 1 trên sàn)
15	export function MonthTrack({ n = 180, cols = 12, spare = 2, tile = 0.34, gap = 0.08, th = 0.07, slab = 0.035, name = 'track' } = {}) {
16	  const g = new THREE.Group(), pitch = tile + gap, years = Math.ceil(n / cols), nmax = n + spare * cols;
17	  const box = (h, f = 1) => new THREE.BoxGeometry(tile * f, h, tile * f);
18	  // lớp trả thêm phủ 72 % mặt ô (vành ink của khoản bắt buộc vẫn thấy); khối năm cùng mặt cắt, cao = 12 lớp (cùng thể tích)
19	  const SF = 0.72;
20	  const tiles = new THREE.InstancedMesh(box(th), mat('#FFFFFF', { emissive: new THREE.Color('#FFFFFF'), emissiveIntensity: 0.12 }), nmax);
21	  const slabs = new THREE.InstancedMesh(box(slab, SF), mat(TRACK.extra, { emissive: new THREE.Color(TRACK.extra), emissiveIntensity: 0.25 }), n);
22	  const lumpH = slab * cols, lumps = new THREE.InstancedMesh(box(lumpH, SF), mat(TRACK.extra, { emissive: new THREE.Color(TRACK.extra), emissiveIntensity: 0.25 }), years);
23	  for (const m of [tiles, slabs, lumps]) { m.castShadow = m.receiveShadow = true; m.frustumCulled = false; g.add(m); }
24	  // vạch 15 năm: thanh mảnh đứng yên dọc theo cột, ngay sau ô n (giữa cột years-1 và years)
25	  const markX = years * pitch - gap / 2, depth = cols * pitch - gap;
26	  const mark = new THREE.Mesh(new THREE.BoxGeometry(0.05, 0.32, depth + 0.5), mat(TRACK.mark, { emissive: new THREE.Color(TRACK.mark), emissiveIntensity: 0.4 }));
27	  mark.position.set(markX, 0.16, -depth / 2 + tile / 2); mark.castShadow = true; g.add(mark);
28	  const pos = (i) => [Math.floor(i / cols) * pitch + tile / 2, -(i % cols) * pitch];   // x, z của tâm ô i (0-based)
29	  const M = new THREE.Matrix4(), col = new THREE.Color(), C = { ink: new THREE.Color(TRACK.ink), warn: new THREE.Color(TRACK.warn), empty: new THREE.Color(TRACK.empty) };
30	  const hide = new THREE.Matrix4().makeScale(0, 0, 0);
31	  tiles.userData.checks = { role: 'mark', series: name, key: `track-${name}-tiles` };
32	  slabs.userData.checks = { role: 'mark', series: name, key: `track-${name}-extra` };
33	  lumps.userData.checks = { role: 'mark', series: name, key: `track-${name}-yearly` };
34	  mark.userData.checks = { role: 'mark', series: name, key: `track-${name}-mark` };
35	  g.userData = { n, cols, pitch, tile, th, years, nmax, markX, depth };
36	  // lit: số ô thường đã đặt (0 … n, thực: ô cuối mọc dần); late: số ô trễ (warn, thực); extra: số cột-năm (0 … years, thực) đã có lớp mỏng,
37	  // trái → phải; gathered: số cột-năm (từ trái) mà lớp mỏng đã gom đi (S23: 12 lớp → một khối); yearly: số cột-năm đã có khối năm;
38	  // markA ∈ [0,1]: vạch 15 năm; pulse ∈ [0,1]: loé nhẹ ô trễ
39	  g.set = ({ lit = n, late = 0, extra = 0, gathered = 0, yearly = 0, markA = 1, pulse = 0 } = {}) => {
40	    for (let i = 0; i < nmax; i++) {
41	      const [x, z] = pos(i), isLate = i >= n, a = isLate ? cl01(late - (i - n)) : cl01(lit - i);
42	      if (a <= 0.002) { tiles.setMatrixAt(i, hide); continue; }
43	      const s = isLate ? 1 : a;   // ô thường mọc từ sàn; ô trễ hiện đủ cỡ, sáng theo phần (như W10)
44	      M.makeScale(1, s, 1).setPosition(x, th * s / 2, z); tiles.setMatrixAt(i, M);
45	      col.copy(C.empty).lerp(isLate ? C.warn : C.ink, isLate ? a * (0.85 + 0.15 * pulse) : 1); tiles.setColorAt(i, col);
46	    }
47	    for (let i = 0; i < n; i++) {
48	      const c = Math.floor(i / cols), a = cl01(extra - c) * cl01(c + 1 - gathered) * cl01(lit - i), [x, z] = pos(i);
49	      if (a <= 0.002) { slabs.setMatrixAt(i, hide); continue; }
50	      M.makeScale(1, a, 1).setPosition(x, th + slab * a / 2 + 0.002, z); slabs.setMatrixAt(i, M);
51	    }
52	    for (let c = 0; c < years; c++) {
53	      const i = c * cols + cols - 1, a = cl01(yearly - c) * cl01(lit - i), [x, z] = pos(i);
54	      if (a <= 0.002) { lumps.setMatrixAt(c, hide); continue; }
55	      M.makeScale(1, a, 1).setPosition(x, th + lumpH * a / 2 + 0.002, z); lumps.setMatrixAt(c, M);
56	    }
57	    for (const m of [tiles, slabs, lumps]) m.instanceMatrix.needsUpdate = true;
58	    if (tiles.instanceColor) tiles.instanceColor.needsUpdate = true;
59	    mark.material.opacity = markA; mark.visible = markA > 0.01;
60	    tiles.userData.checks.level = +Math.min(n, lit).toFixed(2); tiles.userData.checks.late = +late.toFixed(2);
61	    slabs.userData.checks.level = +extra.toFixed(3); lumps.userData.checks.level = +yearly.toFixed(3);
62	  };
63	  // toạ độ thế giới (đã cộng vị trí nhóm) — cho nhãn/ngoặc ở lớp phủ: tâm ô i, mép trái/phải của cột c, mép trước/sau
64	  g.tileAt = (i) => { const [x, z] = pos(i); return [g.position.x + x, g.position.y + th, g.position.z + z]; };
65	  g.colX = (c, side = 0) => g.position.x + c * pitch + (side < 0 ? 0 : side > 0 ? tile : tile / 2);
66	  g.frontZ = () => g.position.z + tile / 2;
67	  g.backZ = () => g.position.z - (cols - 1) * pitch - tile / 2;
68	  g.markWorldX = () => g.position.x + markX;
69	  g.set({});
70	  return g;
71	}
72	
73	// ---------------------------------------------------------------- thanh khoản trả tháng: ink tới warnAbove, phần trên = warn (gốc = tâm đáy)
74	export function PayBar({ w = 0.8, d = 0.5, scale = 1 / 1200, name = 'bar' } = {}) {
75	  const g = new THREE.Group();
76	  const base = new THREE.Mesh(new THREE.BoxGeometry(w, 1, d), mat(TRACK.ink, { emissive: new THREE.Color(TRACK.ink), emissiveIntensity: 0.12 }));
77	  const top = new THREE.Mesh(new THREE.BoxGeometry(w, 1, d), mat(TRACK.warn, { emissive: new THREE.Color(TRACK.warn), emissiveIntensity: 0.3 }));
78	  for (const m of [base, top]) { m.castShadow = m.receiveShadow = true; g.add(m); }
79	  base.userData.checks = { role: 'bar', series: name, key: `pay-${name}` }; top.userData.checks = { role: 'bar', series: name, key: `pay-${name}-above` };
80	  g.userData = { w, d, scale };
81	  // usd: chiều cao (USD/tháng); warnAbove: mức trên đó tô warn; topA ∈ [0,1]: độ hiện phần warn; appear ∈ [0,1]
82	  g.set = ({ usd = 0, warnAbove = Infinity, topA = 1, appear = 1 } = {}) => {
83	    const h = usd * scale * appear, hb = Math.min(h, warnAbove * scale), ht = Math.max(0, h - hb);
84	    base.scale.y = Math.max(0.001, hb); base.position.y = hb / 2; base.visible = hb > 0.002;
85	    top.scale.y = Math.max(0.001, ht); top.position.y = hb + ht / 2; top.visible = ht > 0.002 && topA > 0.01;
86	    top.material.color.set(TRACK.ink).lerp(new THREE.Color(TRACK.warn), topA);
87	    base.userData.checks.value = +Math.min(usd, warnAbove).toFixed(2); top.userData.checks.value = +Math.max(0, usd - warnAbove).toFixed(2);
88	    return h;
89	  };
90	  g.topY = (usd) => usd * scale;
91	  g.set({});
92	  return g;
93	}
94	
95	// ---------------------------------------------------------------- tờ đô la (thẻ phẳng màu tiền + huy hiệu tròn sáng ở giữa; không chữ)
96	export function Bill({ w = 0.62, h = 0.28, d = 0.02, name = 'bill' } = {}) {
97	  const g = new THREE.Group();
98	  const body = new THREE.Mesh(new THREE.BoxGeometry(w, d, h), mat('#5E8C6A', { roughness: 0.7 })); body.castShadow = body.receiveShadow = true;
99	  const seal = new THREE.Mesh(new THREE.CylinderGeometry(h * 0.3, h * 0.3, d * 1.3, 12), mat('#C9D8C4', { roughness: 0.6 }));
100	  const edge = new THREE.Mesh(new THREE.BoxGeometry(w * 0.9, d * 1.2, h * 0.08), mat('#4E7A5A')); edge.position.z = h * 0.36;
101	  const edge2 = edge.clone(); edge2.position.z = -h * 0.36;
102	  g.add(body, seal, edge, edge2);
103	  g.userData.checks = { role: 'mark', series: name, key: `bill-${name}` };
104	  return g;
105	}
